function lassoAppend(lasso, x, y, minDist = 5) {
    const last = lasso[lasso.length - 1];

    if (last === undefined || Math.sqrt(((last[0] - x) ** 2) + ((last[1] - y) ** 2)) > minDist) {
        lasso.push([x, y]);

        return [...lasso];
    }

    return lasso;
}

function isPrototypePolluted() {
